"""Render independently audited six-block scaling evidence; no new samples."""
import csv,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
OUT=Path('results/thrml_spw/all_blocks_clean')
def rows(name):
    with (OUT/name).open() as f:return list(csv.DictReader(f))
def main():
    assert json.loads((OUT/'evidence_audit.json').read_text())['passed'];p=json.loads((OUT/'protocol.json').read_text());m=json.loads((OUT/'manifest.json').read_text());summary=rows('summary.csv');base=rows('baseline_metrics.csv');prefix=rows('prefix_metrics.csv');pair=json.loads((OUT/'paired_summary.json').read_text());fp=float(next(r for r in base if r['condition']=='FP32')['perplexity'])
    fig,ax=plt.subplots(2,2,figsize=(12,8),layout='constrained');x=np.array([12,24]);point=np.array([100*(float(r['relative_perplexity'])-1) for r in summary]);upper=np.array([100*(float(r['bootstrap_relative_upper'])-1) for r in summary]);ax[0,0].plot(x,point,'o',label='Point estimate');ax[0,0].plot(x,upper,'_',ms=14,label='Crossed upper sensitivity bound');ax[0,0].axhline(5,ls='--',color='black',label='Frozen 5% rule');ax[0,0].set(xticks=x,xticklabels=['First 3 blocks','All 6 blocks'],ylabel='PPL increase over FP32 (%)',title='Ideal finite8 controls; native T1024');ax[0,0].legend(fontsize=7)
    allmean=next(r for r in base if r['condition']=='programmed_mean8_all24');names=['FP32','Mean controls\nall24','Native\nfirst12','Native\nall24'];values=[fp,float(allmean['perplexity'])]+[float(r['perplexity']) for r in summary];ax[0,1].plot(range(4),values,'o');ax[0,1].set(xticks=range(4),xticklabels=names,ylabel='Perplexity',title='Mean network is a diagnostic, not E[network]')
    ce=np.array([[float(next(r for r in prefix if int(r['sampling_seed'])==seed and int(r['converted_prefix'])==k)['cross_entropy']) for k in range(25)] for seed in range(5)]);ax[1,0].plot(range(25),100*(np.exp(ce.T-np.log(fp))-1),alpha=.5);ax[1,0].plot(range(25),100*(np.exp(ce.mean(0)-np.log(fp))-1),color='black',lw=2,label='Mean CE then exponentiate');ax[1,0].axhline(5,ls='--',color='black');ax[1,0].set(xlabel='Converted projections in forward order',ylabel='PPL increase (%)',title='All prefixes retained; five sampling seeds');ax[1,0].legend(fontsize=7)
    y=pair['CE_difference'];ax[1,1].errorbar([0],[y],yerr=[[y-pair['CE_sensitivity_low']],[pair['CE_sensitivity_high']-y]],fmt='o',capsize=5);ax[1,1].axhline(0,color='black',ls='--');ax[1,1].set(xticks=[0],xticklabels=['All24 minus shared first12'],ylabel='CE difference (nats/target)',title='Paired crossed seed/bank sensitivity')
    for a in ax.ravel():a.grid(axis='y',alpha=.2)
    fig.savefig('results/thrml_spw/all_blocks_evidence.png',dpi=180);plt.close(fig)
    parts=['# All six Transformer blocks: fixed-regime native scaling test\n']
    parts.append(f'All six blocks\' 24 affine projections now execute through one free THRML p-bit per normalized signed weight: **42,467,328 weights, 51.84% of unique model parameters**. On 2,048 fresh short-context targets, native T1024 perplexity is **{float(summary[1]["perplexity"]):.3f}**, versus **{float(summary[0]["perplexity"]):.3f}** for the shared first-three-block prefix and **{fp:.3f}** for FP32. All five seeds, 120 native operators and both paired neural paths passed independent audits. The goal remains active.\n')
    parts.append('## Frozen design and scope\n')
    parts.append('This fixed-regime scaling test expands beyond the previous 25.92% converted subset without selecting a new sampling budget from test results. The pinned DistilGPT-2 revision is 2290a62682d06624634c1f46a6ad5be0f47f38aa. Every attention QKV/output and MLP up/down matrix in all six blocks is converted (24 matrices). Embeddings, the tied final language-model head, LayerNorm and biases remain deterministic. Thus all Transformer-block matrix weights are converted, but this is **not a fully probabilistic model**. Signed weights use shared group128 lower/span ranges and finite eight-bit [-4,4] unary commands; direct p=raw signed weight is not claimed. All converted nodes are free, including finite approximations to endpoint probabilities.\n')
    parts.append('Five independent sampling seeds use T1024 and banks of eight contexts. Static ideal devices have no gain/offset error, drift or coupling and need no calibration. Native THRML 0.1.4 at commit 2d54cd8404df85bb65703d7e8b4e84e48c1b72a9 supplies every stochastic state; production sums outputs before original nonlinearities. Each later operator receives the actual current stochastic student input. The first twelve outputs are shared exactly between first-three-block and all-six-block conditions, so their paired comparison adds no duplicate prefix sampling. The all-six-block path nevertheless uses twice the free nodes and observed updates of its prefix; it is not a matched-resource superiority comparison.\n')
    parts.append('Thirty-two new nonoverlapping 65-token WikiText-2 windows supply 2,048 targets, excluding all previous recorded text positions. Window count was fixed for available storage before task scoring. Five seeds cross only four whole eight-context banks, so uncertainty has limited resolution. This is a prospective fixed-regime scaling test on one checkpoint and corpus, rather than a validation-selected full-model or broad-task confirmation. No budget rescue or selection follows outcomes.\n')
    parts.append('## Results\n\n| Deterministic control | Perplexity | Token accuracy (%) |\n|---|---:|---:|')
    for r in base:parts.append(f'| {r["condition"]} | {float(r["perplexity"]):.3f} | {100*float(r["token_accuracy"]):.3f} |')
    parts.append('\n| Native conversion | Perplexity | PPL increase (%) | Token accuracy (%) | Upper PPL increase (%) | Point gate | Strict gate |\n|---|---:|---:|---:|---:|---|---|')
    for r in summary:parts.append(f'| {r["converted_projections"]} projections | {float(r["perplexity"]):.3f} | {100*(float(r["relative_perplexity"])-1):.3f} | {100*float(r["token_accuracy"]):.3f} | {100*(float(r["bootstrap_relative_upper"])-1):.3f} | {r["point_passed"]} | {r["passes"]} |')
    parts.append(f'\nAll24 minus first12 has CE difference {pair["CE_difference"]:+.6f} nats/target, PPL ratio {pair["perplexity_ratio"]:.6f}, and crossed CE sensitivity interval [{pair["CE_sensitivity_low"]:+.6f}, {pair["CE_sensitivity_high"]:+.6f}]. Accuracy difference is {100*pair["accuracy_difference"]:+.4f} percentage points, with sensitivity interval [{100*pair["accuracy_sensitivity_low"]:+.4f}, {100*pair["accuracy_sensitivity_high"]:+.4f}]. Intervals resample five seeds crossed with four whole banks, 10,000 times using frozen seed2026116801. They describe sensitivity under exchangeable clusters, not guaranteed coverage or equivalence.\n')
    parts.append('Both prefixes are evaluated against the unchanged point rule PPL/FP32≤1.05 and accuracy loss≤1 percentage point. The strict rule also requires crossed 97.5% CE upper bound≤log(1.05) and accuracy 2.5% lower bound≥−0.01. All 25 prefixes per seed are retained and plotted; intermediate outcomes do not select the conversion subset. The deterministic programmed-mean network separates finite-controller rounding/range error from native sampling diagnostically; applying nonlinearities to mean weights does not equal the expected sampled network. Earlier calibrated failures and all earlier conditions remain unchanged.\n')
    parts.append('## Costs, evidence and limitations\n')
    payload=sum(c['payload_bytes'] for c in p['control_artifacts']);bits=8*payload/p['converted_weights']
    parts.append(f'Production uses {m["native_free_node_updates"]:,} observed free-node updates across five complete all24 cases. The first12 prefix accounts for half that count and is not sampled again. Independent public replay repeats the full production count for verification. The packed command/range/bias payload is {payload:,} bytes, or {bits:.5f} bits per converted weight, excluding runtime arrays, readout and accumulation. One p-bit node does not imply one total memory bit. Wall-clock simulation timings include implementation and compilation costs and are not physical latency estimates. No physical energy, area, sampling-rate, switching or system advantage is established.\n')
    parts.append('Independent source-weight checks regenerated all 42,467,328 command codes, shared ranges and biases. Every native operator was replayed through separately constructed public THRML unary factors and exact integer state frequencies. Independent original-model pre/post-hooks regenerated all 120 runtime input arrays with exact NPY SHA matches and reproduced per-token losses/predictions for both prefixes in every seed. A separate audit replays all five deterministic baselines, checks 125 prefix rows, all counters, all 60,000 bootstrap values, quality rules and causal output hashes. Unique native output arrays and per-token evidence are preserved. Runtime inputs are regenerated as needed and removed only after verified hash/replay checks.\n')
    parts.append('An initial launch failed before native sampling because an IO import unnecessarily depended on PyTorch in the THRML-only environment. That failed execution, baseline arrays, stderr and source version are preserved under `all_blocks/failed_launch_import/`. The import was corrected to the existing NumPy-only atomic IO helper; scientific settings and decisions were unchanged. A subsequent incomplete launch was stopped after a suspected older validation overlap. A full token-level audit resolved that suspicion as a false alarm: offsets refer to different validation/test splits, with different token rows. Every archived token row was checked against the correct source stream. All of its native outputs/protocols remain under `all_blocks/`; the clean study conservatively excludes every known validation/test numeric offset vector and the stopped launch test positions before new scoring. Its 13 completed operators and observed-update cost are counted separately from the final study. The completed launch cache is verified without new native samples or manifest changes.\n')
    parts.append('The result broadens operator conversion but leaves nonideal/calibrated broader conversion, adaptive policies, probability-aware Transformer fine-tuning, embedding/head conversion, long-context tasks, multiple checkpoints and physical hardware costs open. Lower quality at the fixed regime should motivate validation-only allocation/training with separate confirmation, rather than a claim that the original method is disproved.\n')
    parts.append('## Reproduction\n\n```bash\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.all_blocks_transformer\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.audit_all_blocks_paths\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.verify_all_blocks\n.venv-thrml/bin/python -m research.thrml_spw.all_blocks_report\n```\n')
    Path('results/thrml_spw/ALL_BLOCKS_REPORT.md').write_text('\n'.join(parts)+'\n');print(json.dumps({'summary':summary,'paired':pair,'control_payload_bits_per_converted_weight':bits,'goal_status':'active'},indent=2))
if __name__=='__main__':main()
